import java.util.ArrayList;
import java.util.Arrays;

ArrayList<String> frutas = new ArrayList<>(
    Arrays.asList("manzana", "banana", "cereza")
);
System.out.println(frutas);

ArrayList<String> frutas = new ArrayList<>(
    Arrays.asList("manzana", "banana", "cereza")
);
System.out.println(frutas.get(0));   // manzana
System.out.println(frutas.get(frutas.size()-1)); // cereza

ArrayList<String> frutas = new ArrayList<>(
    Arrays.asList("manzana", "banana", "cereza")
);
frutas.set(1, "kiwi");
System.out.println(frutas);

ArrayList<String> frutas = new ArrayList<>(
    Arrays.asList("manzana", "banana")
);
frutas.add("cereza");       // al final
frutas.add(1, "naranja");   // en posición 1
System.out.println(frutas);

ArrayList<String> frutas = new ArrayList<>(
    Arrays.asList("manzana", "banana", "cereza")
);
System.out.println(frutas.size());  // 3

for (String fruta : frutas) {
    System.out.println(fruta);
}
